import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    if n == 0:
        return 1 # LCM of an empty set is often taken as 1
    numbers = list(range(k, k + n))
    return reduce(lcm, numbers)

# Parameters
K_values = [1, 2, 3, 4, 5]
N_values = [3, 4, 5]

results = {}

# 1. Calculate all x_k values
print("--- Calculated X_k values ---")
for n in N_values:
    results[n] = {}
    print(f"\nFor n={n}:")
    for k in K_values:
        x_k = calculate_x_k(k, n)
        results[n][k] = x_k
        print(f"  x_{k} = lcm({k}, ..., {k+n-1}) = {x_k}")

# 2. Check for x_{k+1} <= x_k
print("\n--- Checking for x_{k+1} <= x_k ---")
all_checks = []
for n in N_values:
    print(f"\nChecking for n={n}:")
    for k in range(1, 5): # We check k=1 to 4, corresponding to k+1=2 to 5
        if n not in results or k not in results[n] or k+1 not in results[n]:
             continue # Should not happen based on setup

        x_k = results[n][k]
        x_k_plus_1 = results[n][k+1]

        is_decreasing_or_equal = x_k_plus_1 <= x_k

        all_checks.append((n, k, x_k, x_k_plus_1, is_decreasing_or_equal))

        print(f"  k={k} vs k+1={k+1}: x_{k+1} ({x_k_plus_1}) <= x_{k} ({x_k})? {is_decreasing_or_equal}")

print("\n--- Summary of Checks (n, k, x_k, x_{k+1}, <=) ---")
for n, k, x_k, x_k_plus_1, is_decreasing_or_equal in all_checks:
    print(f"({n}, {k}): x_{k}={x_k}, x_{k+1}={x_k_plus_1}, Decreasing/Equal: {is_decreasing_or_equal}")

